INSERT INTO sources (source_id, source_type, title, scope) VALUES
 ('SRC_DEE_ENOCHIAN','primary text','John Dee & Edward Kelley, the Enochian diaries (Heptarchia Mystica; Liber Loagaeth; Liber Scientiae / the Aethyrs), Sloane MSS','Renaissance Esoteric')
INSERT INTO _e VALUES
 ('ENT_REN_ENOCHIAN','The Enochian System of John Dee','Collective','Enochian system','angelic revelation; the divine (Enochian) language; theurgic cosmology','B','The integrated angelic-magical system received by John Dee and Edward Kelley 1581-1587 across the Heptarchia Mystica, Liber Loagaeth, and Liber Scientiae (the Aethyrs and Great Table); its component structures are well documented even where individual angel names vary between manuscripts.'),
 ('ENT_REN_CARMARA','Carmara','Enochian king','Enochian angel','chief governance of the Heptarchic kings; presidency of the heptarchic order','B','The overarching/chief king coordinating the seven in the Heptarchia; Dee''s records suggest Carmara and Baligon may be two names/aspects of the same governing king (flagged as a manuscript ambiguity).'),
 ('ENT_REN_BALIGON','Baligon','Enochian king','Enochian angel','government of the air; closely identified with Carmara''s office','C','A Heptarchic king frequently equated with Carmara in Dee''s diaries; the relationship between the names Baligon and Carmara is genuinely ambiguous in the records.'),
 ('ENT_REN_BOBOGEL','Bobogel','Enochian king','Enochian angel','government of his day; commonly associated with wisdom/Mercury','B','One of the seven Heptarchic kings; the Wednesday/Mercury correspondence follows the common reading, but planetary-day assignments vary between reconstructions of Dee''s tables.'),
 ('ENT_REN_BABALEL','Babalel','Enochian king','Enochian angel','government of his day; the waters and martial force (Mars)','B','One of the seven Heptarchic kings, linked to Mars and to dominion over the seas in Dee''s notes; precise planetary-day mapping is subject to manuscript variation.'),
 ('ENT_REN_BNASPOL','Bnaspol','Enochian king','Enochian angel','government of his day; the earth and its riches (Saturn)','B','One of the seven Heptarchic kings, linked to dominion over the earth; the Saturn correspondence follows the standard reading but day/planet assignments are not uniformly fixed.'),
 ('ENT_REN_BYNEPOR','Bynepor','Enochian king','Enochian angel','government of his day; life and the estate of nature (Jupiter)','B','One of the seven Heptarchic kings, associated with life and the universal preservation of nature; the Jupiter correspondence is the common reading and varies between reconstructions.'),
 ('ENT_REN_BNAPSEN','Bnapsen','Enochian king','Enochian angel','government of his day; countering evil spirits','C','One of the seven Heptarchic kings; its day/planet assignment (often given as Friday) is among the least stable in the records and is flagged as uncertain.'),
 ('ENT_REN_HAGONEL','Hagonel','Enochian prince','Enochian angel','princely ministry serving the chief king; mediation of his authority','B','The prince attached to the chief king (Carmara/Baligon) and the most prominent of the seven princes in Dee''s diaries.'),
 ('ENT_REN_BORNOGO','Bornogo','Enochian prince','Enochian angel','princely ministry serving his governing king','C','Listed among the seven Heptarchic princes in Dee''s tables; the exact spelling and the king served vary between manuscript readings (flagged uncertain).'),
 ('ENT_REN_BEFAFES','Befafes','Enochian prince','Enochian angel','princely ministry serving his governing king; associated in some readings with the waters','C','Listed among the seven Heptarchic princes; pairing to a specific king and spelling vary across Dee''s tables (flagged uncertain).'),
 ('ENT_REN_BUTMONO','Butmono','Enochian prince','Enochian angel','princely ministry serving his governing king','C','Listed among the seven Heptarchic princes; the spelling and king served are subject to manuscript variation (flagged uncertain).'),
 ('ENT_REN_BLISDON','Blisdon','Enochian prince','Enochian angel','princely ministry serving his governing king','C','Listed among the seven Heptarchic princes; spelling and king-assignment vary across readings of Dee''s tables (flagged uncertain).'),
 ('ENT_REN_BRALGES','Bralges','Enochian prince','Enochian angel','princely ministry serving his governing king','C','Listed among the seven Heptarchic princes; the spelling and king served vary in the manuscripts (flagged uncertain).'),
 ('ENT_REN_BAGENOL','Bagenol','Enochian prince','Enochian angel','princely ministry serving his governing king','C','Listed among the seven Heptarchic princes; spelling and king-pairing are uncertain across Dee''s tables (flagged uncertain).'),
 ('ENT_REN_WATCHTOWERS','The Four Enochian Watchtowers (Great Table)','Collective','Enochian realm','elemental governance of the four quarters (Air/East, Water/West, Earth/North, Fire/South)','B','The four great elemental tablets of the Great Table received by Dee and Kelley, each governing one element and quarter; the individual square-angels and elemental Great Kings are deliberately not enumerated to avoid invention.'),
 ('ENT_REN_AETHYRS','The Thirty Aethyrs (Aires) of the Enochian System','Collective','Enochian realm','thirty graded spiritual spheres enclosing creation, from lowest to highest heaven','B','Thirty concentric Aethyrs recorded in Liber Scientiae, ascending from TEX (the 30th, lowest) to LIL (the 1st, highest); only the firmly attested example aethyrs are listed individually.'),
 ('ENT_REN_AETHYR_LIL','LIL','cosmological realm','Enochian realm','the first and highest Aethyr, nearest the divine','B','Named in Liber Scientiae as the first (highest) of the thirty Aethyrs; firmly attested in Dee''s records.'),
 ('ENT_REN_AETHYR_TEX','TEX','cosmological realm','Enochian realm','the thirtieth and lowest Aethyr, nearest the material world','B','Named in Liber Scientiae as the thirtieth (lowest) of the thirty Aethyrs; firmly attested in Dee''s records.');
